        'sys.str_129': 'क्षमा करें, आपके स्टोर की नामा इन्वेस्ट क्लाउड प्लेटफ़ॉर्म की सदस्यता समाप्त हो गई है। स्वीकृत पैकेज के नवीनीकरण होने तक अस्थायी अनुमतियाँ रोक दी जाती हैं।',
