        'sys.str_133': 'सऊदी अरब में सर्वश्रेष्ठ ईआरपी प्रणाली के रूप में नामा इन्वेस्ट को क्यों चुनें?',
        'sys.str_134': 'नामा इन्वेस्ट बिक्री के बिंदु (पीओएस), दोहरे लेखांकन और मानव संसाधनों के प्रबंधन के लिए अरब दुनिया में सबसे शक्तिशाली एकीकृत क्लाउड सिस्टम है। विशेष रूप से ZATCA चरण 2 आवश्यकताओं का पूरी तरह से अनुपालन करने के लिए डिज़ाइन किया गया है।',
        'sys.str_135': 'ज़कात और आयकर प्राधिकरण को जोड़ना (ZATCA चरण 2)',
        'sys.str_136': 'नामासॉफ्ट प्रणाली बिना किसी मानवीय हस्तक्षेप के सऊदी इलेक्ट्रॉनिक चालान कानूनों का पूर्ण अनुपालन सुनिश्चित करने के लिए वास्तविक समय में क्रिप्टोग्राफ़िक स्टैम्पिंग और त्वरित प्रतिक्रिया कोड (क्यूआर कोड) बनाने की प्रक्रिया को स्वचालित करती है।',
        'sys.str_137': 'क्लाउड पीओएस',
        'sys.str_138': 'तेज़ और विश्वसनीय कैशियर सिस्टम जो ऑफ़लाइन मोड का समर्थन करता है। कनेक्टिविटी बहाल होते ही यह संगठन की सभी शाखाओं के बीच बिक्री और इन्वेंट्री को सीधे सिंक्रनाइज़ कर देता है, जिससे यह बाजारों और रेस्तरां के लिए सबसे अच्छा विकल्प बन जाता है।',
        'sys.str_139': 'लेखांकन और वित्तीय मार्गदर्शन (डबल एंट्री एपीआई)',
        'sys.str_140': 'एक शक्तिशाली लेखांकन इंजन जो कार्यक्रम में किसी भी गतिविधि (बिक्री, खरीद, रिटर्न, वेतन) के लिए दैनिक प्रविष्टियाँ (जर्नल प्रविष्टियाँ) उत्पन्न करता है। इसमें वैश्विक वित्तीय नींव पर आधारित खातों, अंतिम रिपोर्ट और आय विवरणों का एक बुद्धिमान वृक्ष है।',
